/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3list {	public static final class Attr {		public static final String list = "list-style";		public static final String type = "list-style-type";		public static final String position = "list-style-position";		public static final String image = "list-style-image";	}	public static final class Unsign {		public static final String circle = "circle";		public static final String disc = "disc";		public static final String square = "square"; 			}	public static final class Order {		public static final String arm = "armenian";		public static final String cjk = "cjk-ideographic";		public static final String decimal = "decimal";		public static final String zero = "decimal-leading-zero";		public static final String geo = "georgian";		public static final String heb = "hebrew";		public static final String hira = "hiragana";		public static final String hiraIroha = "hiragana-iroha";		public static final String kata = "katakana";		public static final String kataIroha = "katakana-iroha";		public static final String lowerAlpha = "lower-alpha";		public static final String lowerGreek = "lower-greek";		public static final String lowerLatin = "lower-latin";		public static final String lowerRoman = "lower-roman";		public static final String upperAlpha = "upper-alpha";		public static final String upperLatin = "upper-latin";		public static final String upperRoman = "upper-roman";		public static final String none = "none";	}	public static final class Pos {		public static final String inside = "inside";		public static final String outside = "outside";			}	public Value list(String shorthand) {		return new Value().name(Attr.list).value(shorthand);	}	public Value unsign(String unsign) {		return new Value().name(Attr.type).text(unsign);	}	public Value order(String order) {		return new Value().name(Attr.type).text(order);	}	public Value position(String position) {		return new Value().name(Attr.position).text(position);	}	public Value image(String url) {		return new Value().name(Attr.image).text(String.format("url('%s')", url));	}}